  try{compactEnabled=localStorage.getItem('spaceamp-global-controls-v1')!=='false';}catch{}
  const visibilityLabel=node('label','mostrar SPACEAMP nas outras abas');visibilityLabel.className='spaceamp-privacy';const visibilityInput=node('input');visibilityInput.type='checkbox';visibilityInput.checked=compactEnabled;visibilityInput.id='showGlobalSpaceAmp';visibilityLabel.prepend(visibilityInput);full.append(visibilityLabel);visibilityInput.onchange=()=>{compactEnabled=visibilityInput.checked;try{localStorage.setItem('spaceamp-global-controls-v1',String(compactEnabled));}catch{}route();};
  const reopen=button('♫ SPACEAMP',()=>{compactClosed=false;route();});reopen.id='ampReopen';reopen.setAttribute('aria-label','Abrir SPACEAMP compacto');reopen.setAttribute('aria-controls','globalSpaceAmp');document.body.append(reopen);
